def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds:
    :param tz:
    :return: Time
    """
    # Coerce nanoseconds to an integer value.
    if isinstance(nanoseconds, (int, float)):
        ns = int(nanoseconds)
    else:
        try:
            ns = int(str(nanoseconds).strip())
        except Exception as exc:
            raise ValueError("nanoseconds must be an integer or convertible to int") from exc

    # Create the appropriate time object depending on timezone information.
    if tz is None:
        # Return a timezone‑less time instance (LocalTime).
        try:
            return LocalTime(nanoseconds=ns)
        except NameError as exc:
            raise NameError("LocalTime class is not available in the current context") from exc
    else:
        # Return a time instance with the supplied timezone.
        try:
            return Time(nanoseconds=ns, tz=tz)
        except NameError as exc:
            raise NameError("Time class is not available in the current context") from exc<|return|>

def dehydrate_time(value):
    """ Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return:
    """
    if value is None:
        return None
    try:
        # handle datetime.time or similar objects
        return value.isoformat()
    except AttributeError:
        # if value is already a string or no isoformat method, convert to string
        return str(value)<|return|>

def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return:
    """
    if value is None:
        return None

    # If the point has a coords property that returns a tuple
    if hasattr(value, 'coords'):
        try:
            return tuple(value.coords)
        except Exception:
            pass

    # Fallback to explicit attributes
    coords = []
    for attr in ('x', 'y', 'z'):
        if hasattr(value, attr):
            coords.append(getattr(value, attr))
    return tuple(coords)<|return|>

@classmethod
    def protocol_handlers(cls, protocol_version=None):
        """ Return a dictionary of available Bolt protocol handlers,
        keyed by version tuple. If an explicit protocol version is
        provided, the dictionary will contain either zero or one items,
        depending on whether that version is supported. If no protocol
        version is provided, all available versions will be returned.

        :param protocol_version: tuple identifying a specific protocol
            version (e.g. (3, 5)) or None
        :return: dictionary of version tuple to handler class for all
            relevant and supported protocol versions
        :raise TypeError: if protocol version is not passed in a tuple
        """

        if protocol_version is not None and not isinstance(protocol_version, tuple):
            raise TypeError("protocol_version must be a tuple or None")

        # Retrieve the registry of handlers; fall back to empty dict if not defined
        handlers = getattr(cls, "_protocol_handlers", {})

        if protocol_version is None:
            # Return a copy to prevent accidental mutation of the class attribute
            return dict(handlers)

        # Return a single-item dict if the version is supported, otherwise an empty dict
        if protocol_version in handlers:
            return {protocol_version: handlers[protocol_version]}
        else:
            return {}<|return|>

