def data(self, *keys):
    """ Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    # Assume the record stores field names in self._keys and values in self._values
    if not hasattr(self, "_keys") or not hasattr(self, "_values"):
        raise AttributeError("Record object does not have expected internal storage (_keys and _values).")
    field_names = self._keys
    values = self._values

    # If no keys provided, return all.
    if not keys:
        return {k: v for k, v in zip(field_names, values)}

    result = {}
    for key in keys:
        if isinstance(key, int):
            # Index access
            if key < 0 or key >= len(values):
                raise IndexError("index out of bounds")
            result[field_names[key]] = values[key]
        else:
            # Treat as a field name
            if key in field_names:
                idx = field_names.index(key)
                result[key] = values[idx]
            else:
                result[key] = None
    return result<|return|>

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """
    # Basic validation
    if not isinstance(name, str):
        raise TypeError("name must be a string")
    if not isinstance(fields, (list, tuple)):
        raise TypeError("fields must be a list or tuple")
    if not isinstance(srid_map, dict):
        raise TypeError("srid_map must be a dict")

    # Prepare attributes for the new subclass
    attrs = {"SRID_MAP": srid_map}
    for field in fields:
        attrs[field] = None  # default placeholder value

    # Create and return the new subclass
    return type(name, (Point,), attrs)<|return|>

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    import functools
    import warnings

    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(f"{func.__name__}: {message}", DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        wrapper.__deprecated__ = True
        wrapper.__deprecation_message__ = message
        return wrapper

    return decorator<|return|>

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    if not s:
        return ()
    # Replace common separators with a dot, then split.
    parts = s.replace('-', '.').split('.')
    numbers = []
    for part in parts:
        try:
            numbers.append(int(part))
        except ValueError:
            # Skip any non‑numeric fragment (e.g. "rc1" or "beta").
            continue
    return tuple(numbers)<|return|>

def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """
    Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    import os
    # Work with a mutable list first
    new_cmd = list(cmd)

    # Strip any trailing newlines or carriage returns from every part
    new_cmd = [p.rstrip("\r\n") for p in new_cmd]

    # 1. Remove a shebang line if it appears as the first item (rare but can happen)
    if new_cmd and new_cmd[0].startswith("#!"):
        new_cmd = new_cmd[1:]

    if not new_cmd:
        return ()

    # 2. On Windows, handle paths that contain spaces or special characters.
    if os.name == "nt":
        # Quote the first argument if it contains whitespace or parentheses
        first = new_cmd[0]
        if (
            (" " in first or "(" in first or ")" in first)
            and not (first.startswith('"') and first.endswith('"'))
        ):
            new_cmd[0] = f'"{first}"'

        # Additionally, quote any other argument that contains whitespace and is not quoted
        for i, part in enumerate(new_cmd[1:]):
            if " " in part and not (part.startswith('"') and part.endswith('"')):
                new_cmd[i + 1] = f'"{part}"'

    # 3. Resolve deep‑path shebangs by normalising the path (e.g. removing “./” or “../” components)
    #    This is defensive; it normally only matters when the script is executed via `/usr/bin/env`
    #    on a POSIX system, but keeping it harmless on Windows.
    if new_cmd:
        path = new_cmd[0]
        # Remove any leading “#!/” or “#!” that could be left behind
        if path.startswith("#!"):
            path = path[2:]
        try:
            # Resolve to an absolute path; if it doesn't exist we just keep the original
            abs_path = os.path.abspath(os.path.expanduser(path))
            if os.path.exists(abs_path):
                new_cmd[0] = abs_path
        except Exception:
            pass

    return tuple(new_cmd)<|return|>

def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """
    def decorator(func):
        def wrapper(*args, **kwargs):
            k = key(args, kwargs)
            # Use lock if provided
            if lock:
                lock.acquire()
            try:
                if k in cache:
                    return cache[k]
            finally:
                if lock:
                    lock.release()
            result = func(*args, **kwargs)
            if lock:
                lock.acquire()
            try:
                cache[k] = result
            finally:
                if lock:
                    lock.release()
            return result
        return wrapper
    return decorator<|return|>

def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.
    """
    if not isinstance(maxsize, int):
        raise TypeError('maxsize must be an integer')
    if maxsize < 0:
        raise ValueError('maxsize must be >= 0')

    def decorating_function(user_function):
        hits = misses = 0
        import collections
        cache = collections.OrderedDict()

        def wrapper(*args, **kwargs):
            nonlocal hits, misses
            # Build a cache key from function arguments
            key = args
            if typed:
                key += tuple(type(v) for v in args)
            if kwargs:
                for item in sorted(kwargs.items()):
                    key += item

            if key in cache:
                hits += 1
                cache.move_to_end(key)          # mark as recently used
                return cache[key]

            misses += 1
            result = user_function(*args, **kwargs)
            cache[key] = result
            if maxsize > 0 and len(cache) > maxsize:
                cache.popitem(last=False)       # remove least recently used item
            return result

        def cache_info():
            return (hits, misses, maxsize, len(cache))

        def cache_clear():
            nonlocal hits, misses
            cache.clear()
            hits = misses = 0

        wrapper.cache_info = cache_info
        wrapper.cache_clear = cache_clear
        return wrapper

    return decorating_function<|return|>

