def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    import inspect
    result = {}
    # First, add any explicit interface descriptions stored on the class
    if hasattr(self.__class__, "_attribute_descriptions"):
        result.update(self.__class__._attribute_descriptions)
    # If `all` is True, include all public attributes of the class
    if all:
        for name, member in inspect.getmembers(self.__class__):
            # Skip private and dunder names
            if name.startswith("_"):
                continue
            # Exclude callables (methods, functions, etc.)
            if callable(member):
                continue
            # Attempt to get a docstring or use a default empty string
            desc = getattr(member, "__doc__", "")
            if desc:
                desc = desc.strip()
            result[name] = desc
    return result<|return|>

def names(self, all=False):
    """Return the attribute names defined by the interface."""
