    return sorted(interface.keys())<|return|>

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    # Directly a Source sequence is not allowed
    if isinstance(seq, Source):
        return False

    # If it is a single FillRequest instance, it's okay
    if isinstance(seq, FillRequest):
        return True

    # If it's an iterable, check if any member is a FillRequest
    try:
        for item in seq:
            if isinstance(item, FillRequest):
                return True
    except TypeError:
        # seq is not iterable
        return False

    return False<|return|>

