def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    def _diff(a, b, depth):
        res = {}
        for k, v1 in a.items():
            if k not in b:
                res[k] = v1
            else:
                v2 = b[k]
                if isinstance(v1, dict) and isinstance(v2, dict):
                    if depth == 0:
                        res[k] = v1
                    else:
                        sub = _diff(v1, v2, depth - 1 if depth > 0 else depth)
                        if sub:
                            res[k] = sub
                else:
                    if v1 != v2:
                        res[k] = v1
        return res

    max_depth = level if level == -1 else max(level, 0)
    return _diff(d1, d2, max_depth)<|return|>

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.

            .. code:: python

                # Example:
                labels = {
                    "key1": "valid",
                    "key2": ["invalid"],
                    "$$": "invalid",
                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {"['invalid']": 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """
    # Assume KEY_REGEX and VALUE_REGEX are defined elsewhere.
    # Assume ValidationError accepts a list of error dictionaries as its first argument.
    errors = []

    for key, value in labels.items():
        # Validate key
        if not isinstance(key, str):
            errors.append({str(key): 'expected string or bytes-like object'})
        else:
            if not KEY_REGEX.match(key):
                errors.append({key: f"Label key '{key}' does not match the regex [...]"})

        # Helper to validate a single value element
        def _check_value_element(elem):
            if not isinstance(elem, str):
                errors.append({str(elem): 'expected string or bytes-like object'})
            else:
                if not VALUE_REGEX.match(elem):
                    errors.append({elem: f"Label value '{elem}' does not match the regex [...]"})

        # Validate value
        if isinstance(value, (list, tuple)):
            for elem in value:
                _check_value_element(elem)
        else:
            _check_value_element(value)

    if errors:
        raise ValidationError(errors)<|return|>

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_dict_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (list or dict): partial ``last_applied_manifest`` being
            updated
        observer_schema (list): partial ``observer_schema``
        response (dict): partial response from the Kubernetes API.

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present
    """
    # If last_applied_manifest is a list, we treat each element as a
    # mapping with a ``name`` key.  If it is a dict we simply
    # assign missing keys.
    if isinstance(last_applied_manifest, list):
        for key in observer_schema:
            # Key could be a plain string or a mapping with a ``name`` field
            if isinstance(key, dict):
                prop = key.get("name") or key.get("key") or key.get("field")
            else:
                prop = key
            if prop is None:
                continue

            if prop in response:
                # Skip if already present in the list
                if not any(
                    isinstance(entry, dict) and entry.get("name") == prop
                    for entry in last_applied_manifest
                ):
                    last_applied_manifest.append(
                        {"name": prop, "value": response[prop]}
                    )
    elif isinstance(last_applied_manifest, dict):
        for key in observer_schema:
            if isinstance(key, dict):
                prop = key.get("name") or key.get("key") or key.get("field")
            else:
                prop = key
            if prop and prop in response and prop not in last_applied_manifest:
                last_applied_manifest[prop] = response[prop]
    else:
        raise TypeError(
            "last_applied_manifest must be a list or dict, got %s"
            % type(last_applied_manifest).__name__
        )

    return last_applied_manifest<|return|>

def format(
        self,
        sql: AnyStr,
        params: Union[Dict[Union[str, int], Any], Sequence[Any]],
    ) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
        """Convert the SQL query to use the out-style parameters instead of
        the in-style parameters.

        *sql* (:class:`str` or :class:`bytes`) is the SQL query.

        *params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
        contains the set of in-style parameters. It maps each parameter
        (:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
        is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
        If :attr:`.SQLParams.in_style` is an ordinal parameter style, then
        *params* must be a :class:`~collections.abc.Sequence`.

        Returns a :class:`tuple` containing:

        - The formatted SQL query (:class:`str` or :class:`bytes`).

        - The set of converted out-style parameters (:class:`dict` or
          :class:`list`).
        """
        if not hasattr(self, "in_style") or not hasattr(self, "out_style"):
            raise AttributeError(
                "SQLParams object must have both 'in_style' and 'out_style' attributes"
            )

        # Validate parameters according to style
        if self.in_style == "named":
            if not isinstance(params, Mapping):
                raise TypeError("Named parameters must be provided as a mapping")
        elif self.in_style in ("ordinal", "qmark"):
            if not isinstance(params, Sequence) or isinstance(params, (str, bytes)):
                raise TypeError("Ordinal parameters must be provided as a sequence")
        else:
            raise ValueError(f"Unsupported in_style: {self.in_style}")

        # Convert byte sql to str for regex processing, keep original type for result
        is_bytes = isinstance(sql, (bytes, bytearray))
        sql_str = sql.decode("utf-8") if is_bytes else sql

        # Prepare containers for new SQL and new params
        new_sql_parts = []
        new_params = []
        param_index = 1  # Used for ordinal numbering

        # Helper to produce out placeholder
        def out_placeholder(index: int = None) -> str:
            placeholder = self.out_style
            if placeholder == "%s":
                return placeholder
            if placeholder == "?":
                return placeholder
            # Assume style like $%d
            if placeholder.startswith("$") and "d" in placeholder:
                if index is None:
                    raise ValueError("Ordinal out_style placeholder requires an index")
                return placeholder.replace("%d", str(index))
            # Default fallback
            return placeholder

        if self.in_style == "named":
            import re

            pattern = re.compile(r":([A-Za-z_][A-Za-z0-9_]*)")
            pos = 0
            for m in pattern.finditer(sql_str):
                new_sql_parts.append(sql_str[pos : m.start()])
                param_name = m.group(1)
                if param_name not in params:
                    raise KeyError(f"Parameter '{param_name}' not found in params mapping")
                new_sql_parts.append(out_placeholder())
                new_params.append(params[param_name])
                pos = m.end()
            new_sql_parts.append(sql_str[pos:])
        else:
            # Ordinal style (qmark or ordinal)
            import re

            pattern = re.compile(r"\?")
            pos = 0
            for m in pattern.finditer(sql_str):
                new_sql_parts.append(sql_str[pos : m.start()])
                new_sql_parts.append(out_placeholder(param_index))
                if isinstance(params, Sequence) and not isinstance(params, (str, bytes)):
                    try:
                        new_params.append(params[param_index - 1])
                    except IndexError:
                        raise IndexError(
                            f"Parameter index {param_index} out of range for provided params"
                        )
                else:
                    raise TypeError("Params must be a sequence for ordinal style")
                param_index += 1
                pos = m.end()
            new_sql_parts.append(sql_str[pos:])

        new_sql = "".join(new_sql_parts)
        if is_bytes:
            new_sql = new_sql.encode("utf-8")

        # Return params in original type if possible
        if isinstance(params, Mapping):
            # keep mapping but values ordered as they appear
            return new_sql, dict(enumerate(new_params, start=1))
        else:
            return new_sql, new_params
<|return|>

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    import os

    # Ensure path exists and is a directory
    if not os.path.isdir(path):
        return False

    # Basic structural checks: expect 'manifest' and 'objects' directories
    manifest_dir = os.path.join(path, 'manifest')
    objects_dir = os.path.join(path, 'objects')
    if not os.path.isdir(manifest_dir) or not os.path.isdir(objects_dir):
        return False

    # Collect existing object identifiers
    object_ids = {d for d in os.listdir(objects_dir) if os.path.isdir(os.path.join(objects_dir, d))}

    # Validate that each manifest file references existing objects
    for mf_name in os.listdir(manifest_dir):
        if not mf_name.endswith('.txt'):
            continue
        mf_path = os.path.join(manifest_dir, mf_name)
        try:
            with open(mf_path, 'r', encoding='utf-8') as mf_file:
                for line in mf_file:
                    line = line.strip()
                    if not line:
                        continue
                    parts = line.split()
                    obj_id = parts[0]
                    if obj_id not in object_ids:
                        return False
        except Exception:
            # Any I/O or decoding error marks invalid
            return False

    # If all checks pass, consider the OCFL object valid
    return True<|return|>

def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    # Inventory must be a dictionary or an object that behaves like one
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a mapping type, got %r" % type(inventory).__name__)

    # Determine the specification version that will be used for validation
    # Start with the instance's default spec_version
    spec_version = getattr(self, "spec_version", None)
    if spec_version is None:
        raise AttributeError("Instance does not have a 'spec_version' attribute")

    if extract_spec_version:
        # The type field may encode a specification version; try to extract it
        type_val = inventory.get("type")
        if isinstance(type_val, str):
            # Common convention: 'inventory_v1.2' or 'inventory:1.2'
            if "_v" in type_val:
                parts = type_val.split("_v", 1)
                if len(parts) == 2:
                    potential = parts[1]
                    # Optional: ensure it looks like a version string
                    if potential.replace(".", "").isdigit():
                        spec_version = potential
            elif ":" in type_val:
                parts = type_val.split(":", 1)
                if len(parts) == 2:
                    potential = parts[1]
                    if potential.replace(".", "").isdigit():
                        spec_version = potential

    # Simple validation checks based on the determined spec version
    # These checks are illustrative; replace or extend them as needed for the real spec.
    errors = []

    # Example rule: version 1.x must contain an 'items' key that is a list
    if spec_version.startswith("1."):
        if "items" not in inventory:
            errors.append("Missing required 'items' key for spec version %s" % spec_version)
        elif not isinstance(inventory["items"], list):
            errors.append("'items' must be a list for spec version %s" % spec_version)

    # Example rule: for version 2.x, 'metadata' must be present and a dict
    if spec_version.startswith("2."):
        if "metadata" not in inventory:
            errors.append("Missing required 'metadata' key for spec version %s" % spec_version)
        elif not isinstance(inventory["metadata"], dict):
            errors.append("'metadata' must be a dict for spec version %s" % spec_version)

    # Generic checks: all string keys and non-None values
    for k, v in inventory.items():
        if not isinstance(k, str):
            errors.append("Key %r is not a string" % k)
        if v is None:
            errors.append("Key %r has a value of None" % k)

    if errors:
        raise ValueError("Inventory validation failed: %s" % "; ".join(errors))

    # If we reach this point, the inventory passes validation
    return True<|return|>

def check_digests_present_and_used(self, manifest_files, digests_used):
        """Check all digests in manifest that are needed are present and used."""
        missing = []
        for fname, digest in manifest_files.items():
            if digest not in digests_used:
                missing.append((fname, digest))

        unused = []
        for digest in digests_used:
            if digest not in manifest_files.values():
                unused.append(digest)

        if missing:
            msg = 'Missing digests for files: ' + ', '.join(f'{fname}:{digest}' for fname, digest in missing)
            raise ValueError(msg)

        if unused:
            msg = 'Unmatched digests used but not in manifest: ' + ', '.join(unused)
            raise ValueError(msg)<|return|>

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    logical_path_map = {}
    for key, meta in inventory.items():
        # `meta` should contain 'logical_path' and 'version'.
        try:
            logical_path = meta['logical_path']
            file_version = meta['version']
            content_file = meta.get('content_file', key)
        except (TypeError, KeyError):
            continue  # skip entries that don't have the expected structure

        # Include files for the given version or later versions
        if file_version >= version:
            logical_path_map.setdefault(logical_path, set()).add(content_file)

    return logical_path_map

<|return|>

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # basic type checks
    if not isinstance(fixity, dict):
        raise ValueError("The `fixity` argument must be a dictionary")

    if not hasattr(manifest_files, "__contains__"):
        raise ValueError("The `manifest_files` argument must be a collection")

    # Check each entry in the fixity block
    for fname, info in fixity.items():
        if fname not in manifest_files:
            raise ValueError(f"Fixity references unknown file '{fname}' not found in the manifest")

        if not isinstance(info, dict):
            raise ValueError(f"Fixity entry for '{fname}' must be a dictionary")

        if "checksum" not in info:
            raise ValueError(f"Missing 'checksum' in the fixity entry for '{fname}'")

        # If a 'size' attribute exists in the manifest entry we can optionally
        # verify that it matches the one stored in the fixity block.  This step
        # is guarded so that it does not raise errors if the manifest does not
        # contain size information.
        manifest_entry = None
        if hasattr(manifest_files, "get"):
            manifest_entry = manifest_files.get(fname)
        if isinstance(manifest_entry, dict) and "size" in manifest_entry:
            if "size" in info and info["size"] != manifest_entry["size"]:
                raise ValueError(
                    f"Size mismatch for '{fname}': fixity size {info['size']} "
                    f" != manifest size {manifest_entry['size']}"
                )

    # Optional: Ensure every file in the manifest has a corresponding fixity
    for fname in manifest_files:
        if fname not in fixity:
            raise ValueError(f"File '{fname}' in manifest has no corresponding fixity entry")

    return True<|return|>

