def pretty(self, indent=0, debug=False):
    """Return a pretty formatted representation of self."""
    # Create indentation string
    indent_str = ' ' * (indent * 4)

    # Gather attribute representations
    attrs = []
    for key, value in self.__dict__.items():
        # Skip private/internal attributes and collections of children
        if key.startswith('_'):
            continue
        if isinstance(value, (list, tuple)) and not debug:
            # Skip printing lists unless debug is requested
            continue
        attrs.append(f"{key}={value!r}")

    # Start with the class name and attributes
    if attrs:
        rep = f"{indent_str}{self.__class__.__name__}(" + ", ".join(attrs) + ")"
    else:
        rep = f"{indent_str}{self.__class__.__name__}"

    # Recursively include child elements if any
    children = []
    # Try to get children via iteration (common in XML/element APIs)
    try:
        for child in self:
            children.append(child)
    except TypeError:
        # If not iterable, maybe have a 'children' attribute
        if hasattr(self, "children"):
            children = list(self.children)

    if children:
        child_reprs = [child.pretty(indent + 1, debug) for child in children]
        rep += ":\n" + "\n".join(child_reprs)

    return rep<|return|>

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    import sys
    if sys.version_info[0] < 3:
        def wrapper(self, *args, **kwargs):
            result = namefunc(self, *args, **kwargs)
            if isinstance(result, unicode):
                try:
                    return result.encode('utf-8')
                except UnicodeEncodeError:
                    return result.encode('latin-1', 'ignore')
            return result
        return wrapper
    else:
        return namefunc<|return|>

