def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    # Assume the StorageRoot instance is iterable over the objects it contains.
    # If this is not true, replace the loop with the appropriate traversal logic.
    for obj in self:
        num_objects += 1
        object_is_valid = True

        # Validate the object itself if requested
        if validate_objects:
            try:
                obj.validate()
            except Exception as exc:
                object_is_valid = False
                if show_warnings:
                    print(f"Validation warning: Object {obj} failed validation: {exc}")

        # Check the digest hash if requested
        if check_digests:
            try:
                obj.check_digest()
            except Exception as exc:
                object_is_valid = False
                if show_warnings:
                    print(f"Digest warning: Object {obj} digest mismatch: {exc}")

        if object_is_valid:
            good_objects += 1

    return num_objects, good_objects<|return|>

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os
    import re

    if not os.path.exists(path):
        return f"Path does not exist: {path}"

    # Helper to inspect a namaste file given its full path
    def inspect_namaste(namaste_path):
        try:
            with open(namaste_path, 'r', encoding='utf-8') as fh:
                first_line = fh.readline().strip()
        except Exception as exc:
            return f"Error reading namaste file '{namaste_path}': {exc}"
        # The root namaste file typically contains the string 'repo' on the first line
        if first_line == "repo":
            return "root"
        else:
            return "object"

    # If the path is a file itself
    if os.path.isfile(path):
        basename = os.path.basename(path)
        if re.match(r"^0=.*$", basename):
            return inspect_namaste(path)
        else:
            # Unknown file type – treat as a generic file
            return "file"

    # If the path is a directory
    if os.path.isdir(path):
        for entry in os.listdir(path):
            if re.match(r"^0=.*$", entry):
                full_path = os.path.join(path, entry)
                result = inspect_namaste(full_path)
                # If inspect returned a descriptor other than error string
                if result in ("root", "object"):
                    return result
                else:
                    # it's an error string; return it
                    return result
        # No namaste file found: not an OCFL root/object
        return "file"

    # If neither file nor directory (unlikely)
    return "unknown"<|return|>

