def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    base = len(alphabet)
    if base <= 1:
        raise ValueError("Alphabet must contain at least two characters")
    # Build mapping from character to its value
    char_to_val = {ch: i for i, ch in enumerate(alphabet)}
    result = 0
    for ch in string:
        try:
            val = char_to_val[ch]
        except KeyError:
            raise ValueError(f"Invalid character {ch!r} not in alphabet") from None
        result = result * base + val
    return result<|return|>

