def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import sys
    if platform == 'this':
        if sys.platform.startswith('win'):
            platform = 0
        else:
            platform = 1
    if platform == 1:
        # POSIX: use a regex that respects quotes and escape sequences
        token_re = re.compile(r'''(?:"(?:\\.|[^"])*"|'(?:\\.|[^'])*'|[^ \t\r\n]+)''')
    elif platform == 0:
        # Windows: similar, but backslashes before quotes are preserved
        token_re = re.compile(r'''(?:"(?:\\.|[^"])*"|'(?:\\.|[^'])*'|[^ \t\r\n]+)''')
    else:
        raise ValueError(f"Unsupported platform value: {platform}")

    tokens = []
    for m in token_re.finditer(s):
        token = m.group(0)
        if len(token) >= 2 and ((token[0] == token[-1]) and token[0] in ('"', "'")):
            # Strip surrounding quotes
            token = token[1:-1]
            # Handle escape sequences inside quotes
            # Replace escaped backslashes and escaped quotes
            token = token.replace(r'\\', '\\')
            token = token.replace(r'\\"', '"')
            token = token.replace(r"\\'", "'")
        tokens.append(token)
    return tokens<|return|>

def _resolve_string(matcher):
    """
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    """
    # Helper to extract name and default from different matcher types
    if isinstance(matcher, (list, tuple)):
        name = matcher[0]
        default = matcher[1] if len(matcher) > 1 else None
    else:
        name = getattr(matcher, 'name', None)
        default = getattr(matcher, 'default', None)

    if name is None:
        raise ValueError("Matcher must contain a 'name' attribute or first element defining the environment variable name.")

    if name in os.environ:
        return os.environ[name]
    if default is not None:
        return default
    raise KeyError(f"Environment variable '{name}' is not set and no default value was provided.")<|return|>

