def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # If seq is already one of the common sequence types, just return it.
    if isinstance(seq, (list, tuple, set, frozenset, str, bytes, bytearray, memoryview)):
        return seq, type(seq)

    # Try to convert seq to a concrete sequence.
    try:
        if hasattr(seq, "__len__"):
            # Already has a length, likely a sequence-like iterable.
            data = list(seq)
        else:
            # seq might be an iterator or generator.
            # If a buffer size was supplied, only collect up to that many elements.
            if bufsize is not None:
                data = []
                for i, item in enumerate(seq):
                    if i >= bufsize:
                        break
                    data.append(item)
            else:
                data = list(seq)
    except TypeError:
        raise ValueError("The argument 'seq' must be an iterable or a sequence type")

    return data, type(data)<|return|>

def verifyClass(iface, candidate, tentative=False):
    """Verify that the *candidate* might correctly provide *iface*."""
    if not isinstance(iface, type):
        raise TypeError("iface must be a class or interface type")

    # Support for checking class inheritance
    if isinstance(candidate, type):
        if issubclass(candidate, iface):
            return True

    # For instances, ensure all public attributes of iface are present
    missing = []
    for attr in dir(iface):
        if attr.startswith('_'):
            # skip private and special attributes
            continue
        if not hasattr(candidate, attr):
            missing.append(attr)

    if missing:
        if tentative:
            return False
        raise TypeError(
            f"Candidate {candidate!r} is missing required attributes "
            f"{', '.join(missing)} from interface {iface.__name__}"
        )

    return True<|return|>

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    # Determine the most derived metaclass from the given bases
    if explicit_mc is None:
        candidate = None
        for base in bases:
            base_meta = type(base)
            if candidate is None:
                candidate = base_meta
                continue
            # Skip if the current candidate already is the same as this one
            if candidate is base_meta:
                continue
            # Prefer the more derived metaclass
            if issubclass(candidate, base_meta):
                continue
            if issubclass(base_meta, candidate):
                candidate = base_meta
                continue
            # No subclass relationship -> conflict
            raise TypeError(f"metaclass conflict: {candidate.__name__} vs {base_meta.__name__}")
    else:
        # Explicit metaclass was supplied
        if not isinstance(explicit_mc, type):
            raise TypeError(f"explicit metaclass must be a type, got {explicit_mc!r}")
        candidate = explicit_mc
        # Ensure compatibility with each base's metaclass
        for base in bases:
            base_meta = type(base)
            if not issubclass(candidate, base_meta) and not issubclass(base_meta, candidate):
                raise TypeError(f"explicit metaclass {candidate.__name__} not compatible "
                                f"with base metaclass {base_meta.__name__}")
    # If no bases and no explicit metaclass, default to type
    if candidate is None:
        return type
    return candidate<|return|>

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    return super().popitem()<|return|>

def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    # 1. Check if request is a public message
    if isinstance(request, dict):
        if 'public_message' in request or 'public' in request:
            return True
        if 'private_message' in request or 'private' in request:
            return True
        if 'legacy_payload' in request:
            return True
    else:
        if hasattr(request, 'public_message'):
            return True
        if hasattr(request, 'private_message'):
            return True
        if hasattr(request, 'legacy_payload'):
            return True
    return False<|return|>

def identify_request(request: RequestType) -> bool:
    """Try to identify whether this is a Matrix request"""
    # If the request is None or empty, we cannot identify it.
    if request is None:
        return False

    # 1) Check for a direct `type` attribute or key that indicates a Matrix request.
    try:
        if getattr(request, "type", None) == "matrix":
            return True
        if isinstance(request, dict) and request.get("type") == "matrix":
            return True
    except Exception:
        pass

    # 2) If the request is HTTP‑style, look for a `Content‑Type` header that might
    # mention the Matrix protocol.
    try:
        if hasattr(request, "headers"):
            content_type = request.headers.get("Content-Type", "")
            if "matrix" in content_type.lower():
                return True
    except Exception:
        pass

    # 3) Check for typical Matrix JSON keys that are present in a request.
    try:
        if isinstance(request, dict):
            # A common Matrix request has a `type` field beginning with an
            # underscore or a specific hard‑coded string.
            if request.get("type") in ("m.room.message", "m.room.create"):
                return True
    except Exception:
        pass

    # If none of the heuristics matched, we cannot safely say this is a Matrix
    # request.
    return False<|return|>

def format_dt(dt):
    """Format a datetime in the way that D* nodes expect."""
    if hasattr(dt, "hour"):
        return dt.strftime("%Y-%m-%dT%H:%M:%S")
    try:
        return dt.strftime("%Y-%m-%d")
    except Exception as exc:
        raise TypeError("dt must be a datetime or date object") from exc<|return|>

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    import re

    # Convert markdown-style links [text](url) to HTML anchors
    def _markdown_repl(match):
        content, url = match.group(1), match.group(2)
        return f'<a href="{url}" rel="nofollow" target="_blank">{content}</a>'

    text = re.sub(r'\[([^\]]+)\]\(([^)]+)\)', _markdown_repl, text)

    # Find plain URLs and convert them to anchors
    url_pat = re.compile(r'(https?://[^\s<>\]\[\(\)\'"]+)')
    def _url_repl(match):
        url = match.group(0)
        # Do not double‑link if already inside an <a> tag
        start, end = match.span()
        if text[max(0, start-5):start].strip().endswith('>') and text[end:end+2].strip().startswith('</a'):
            return url  # already linkified
        return f'<a href="{url}" rel="nofollow" target="_blank">{url}</a>'

    text = url_pat.sub(_url_repl, text)

    # Optionally add a CSS class or data attribute to all anchors (simple example)
    anchor_pat = re.compile(r'(<a[^>]+href="[^"]+"[^>]*>)')
    def _add_attrs(match):
        tag = match.group(0)
        if 'class="' in tag:
            return tag.replace('class="', 'class="linkified ', 1)
        else:
            return tag.replace('>', ' class="linkified">', 1)

    text = anchor_pat.sub(_add_attrs, text)

    return text<|return|>

def fetch_content_type(url: str) -> Optional[str]:
    """Fetch the HEAD of the remote url to determine the content type."""
    try:
        resp = requests.head(url, allow_redirects=True, timeout=10)
        return resp.headers.get('content-type')
    except Exception:
        return None<|return|>

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    if not isinstance(tag, str) or not tag:
        return False
    if len(tag) > 20:
        return False
    if not tag[0].isalpha():
        return False
    for ch in tag[1:]:
        if not (ch.isalnum() or ch in "-_"):
            return False
    return True<|return|>

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    children_dict = {}
    for child in node:
        children_dict[child.tag] = child
    return children_dict<|return|>

def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    base = url.rstrip('/')
    if document_path:
        path = document_path.lstrip('/')
    else:
        path = '.well-known/nodeinfo/2.0'
    href = f"{base}/{path}"
    return {
        "links": [
            {
                "rel": "http://nodeinfo.diaspora.software/ns/1.0",
                "type": "application/json",
                "href": href
            }
        ]
    }<|return|>

def parse_diaspora_webfinger(document: str) -> Dict:
    """Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET

    # Attempt to parse as JSON first
    try:
        return json.loads(document)
    except (json.JSONDecodeError, ValueError):
        pass

    # Fallback to XRD parsing
    root = ET.fromstring(document)
    ns = {'xrd': 'http://docs.oasis-open.org/ns/xri/xrd-1.0'}

    subject_el = root.find('xrd:Subject', ns)
    subject = subject_el.text if subject_el is not None else None

    links = []
    for link_el in root.findall('xrd:Link', ns):
        href = link_el.attrib.get('href')
        rel = link_el.attrib.get('rel')
        if href:
            links.append({'rel': rel, 'href': href})

    return {'subject': subject, 'links': links}<|return|>

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """Try to retrieve an RFC7033 webfinger document. Does not raise if it fails."""
    try:
        if not handle or '@' not in handle:
            return None
        domain = handle.split('@', 1)[1]
        resource = f"acct:{handle}"
        url = f"https://{domain}/.well-known/webfinger?resource={resource}"
        resp = requests.get(url, timeout=5, allow_redirects=True, verify=True)
        if resp.status_code != 200:
            return None
        return resp.text
    except Exception:
        return None<|return|>

def dict_insert(dic, val, key, *keys):
    """insert a value of a nested key into a dictionary

    to insert value for a nested key, all ancestor keys should be given as
    method's arguments

    example:
      dict_insert({}, 'val', 'key1.key2'.split('.'))

    :param dic: a dictionary object to insert the nested key value into
    :param val: a value to insert to the given dictionary
    :param key: first key in a chain of key that will store the value
    :param keys: sub keys in the keys chain
    """
    if not isinstance(dic, dict):
        raise TypeError("dic must be a dictionary")
    if not keys:
        dic[key] = val
    else:
        if key not in dic or not isinstance(dic[key], dict):
            dic[key] = {}
        dict_insert(dic[key], val, *keys)<|return|>

