def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    def _rec(d, path):
        if not isinstance(d, dict):
            return d
        # Handle an explicit include directive
        if "include" in d:
            include_ids = d.pop("include")
            if isinstance(include_ids, str):
                include_ids = [include_ids]
            for inc_id in include_ids:
                if inc_id not in parser_dict:
                    raise KeyError(f"Include key {inc_id!r} not found in parser_dict at path {'.'.join(map(str, path))}")
                inc_val = parser_dict[inc_id]
                # Recursively resolve inside the included value
                resolved_inc = _rec(inc_val, path + [inc_id])
                # Merge the resolved include into the current dict
                for k, v in resolved_inc.items():
                    if k not in d:
                        d[k] = v
                    else:
                        # If both are dicts, merge recursively
                        if isinstance(d[k], dict) and isinstance(v, dict):
                            d[k] = _rec(v, path + [inc_id, k])
                        else:
                            # Otherwise, override with the included value
                            d[k] = v
        # Recurse into nested dictionaries or lists
        for key, val in list(d.items()):
            if isinstance(val, dict):
                d[key] = _rec(val, path + [key])
            elif isinstance(val, list):
                new_list = []
                for idx, item in enumerate(val):
                    if isinstance(item, dict):
                        new_list.append(_rec(item, path + [key, idx]))
                    else:
                        new_list.append(item)
                d[key] = new_list
        return d

    return _rec(parser_dict, [])<|return|>

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    # Grab the specification dictionary, if it exists
    spec = getattr(self, 'spec', {})
    defaults = {}

    # First, take any values that the spec directly provides
    for key, value in spec.items():
        defaults[key] = value

    # Next, merge in any class‑level defaults that are not overridden by the spec
    class_defaults = getattr(self.__class__, 'DEFAULTS', {})
    for key, value in class_defaults.items():
        defaults.setdefault(key, value)

    return defaults<|return|>

def get_deprecated_args(self):
    """Returning dict with options which deprecate others. """
    return {}<|return|>

def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    # a list of deprecated argument names; subclasses can override
    deprecated_keys = getattr(self, 'deprecated_keys', [])

    # Merge CLI and answer file arguments, giving precedence to CLI
    merged_args = {}
    if answer_file_args:
        merged_args.update(answer_file_args)
    if cli_args:
        merged_args.update(cli_args)

    for key in deprecated_keys:
        if key in merged_args:
            import warnings
            warnings.warn(f"Argument '{key}' is deprecated. Current value: {merged_args[key]}", DeprecationWarning)<|return|>

def get_parser_option_specs(self, command_name):
        """Gets all the options for the specified command

        :param command_name: the command name (main, virsh, ospd, etc...)
        :return: the list of all command options
        """
        # If the parsers map is missing or does not contain the command, return an empty list.
        if not hasattr(self, 'parsers') or command_name not in self.parsers:
            return []

        parser = self.parsers[command_name]

        # First try the most explicit API.
        if hasattr(parser, "get_option_specs"):
            return parser.get_option_specs()

        # Fallback to common attribute names that might hold the options.
        if hasattr(parser, "options"):
            return list(parser.options)

        if hasattr(parser, "option_spec"):
            spec = parser.option_spec
            # Some parsers return a dict of name -> spec
            if isinstance(spec, dict):
                return list(spec.values())
            return [spec]

        # If neither API is present, indicate no options were found.
        return []<|return|>

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    if not hasattr(self, 'options') or command_name not in self.options:
        raise KeyError(f"Command {command_name!r} not found in options.")
    cmd_opts = self.options[command_name]
    if argument_name not in cmd_opts:
        raise KeyError(f"Option {argument_name!r} not found for command {command_name!r}.")
    return cmd_opts[argument_name]<|return|>

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when`` condition
    """
    required = []

    for opt in options_spec:
        cond = opt.get("required_when")
        if not cond:
            continue

        # Support a single condition given as a tuple or a list/tuple of tuples
        if isinstance(cond, (tuple, list)):
            if all(args.get(a) == v for a, v in cond):
                required.append(opt.get("arg") or opt.get("name"))
                continue

        # Support a dictionary of conditions: {arg: expected_value, ...}
        if isinstance(cond, dict):
            if all(args.get(a) == v for a, v in cond.items()):
                required.append(opt.get("arg") or opt.get("name"))
                continue

        # If ``required_when`` is a callable that decides based on the args
        if callable(cond):
            try:
                if cond(args):
                    required.append(opt.get("arg") or opt.get("name"))
            except Exception:
                # ignore exceptions from user supplied callables
                pass

    return required<|return|>

def validate_length_args(self, args):
        """Check if value of arguments is not longer than length specified.

        :param args: The received arguments.
        """
        max_len = getattr(self, 'length', None)
        if max_len is None:
            # No maximum length defined; nothing to check
            return

        for name, value in args.items():
            # Only check string-like values that have a length
            try:
                length = len(value)
            except Exception:
                continue
            if length > max_len:
                raise ValueError(
                    f"Argument '{name}' exceeds maximum allowed length of {max_len} (got {length})")<|return|>

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    for key, value in args.items():
        if hasattr(self, 'choices') and key in self.choices:
            allowed = self.choices[key]
            if value not in allowed:
                raise ValueError(f"Invalid value for argument '{key}': {value}. "
                                 f"Expected one of {allowed}.")<|return|>

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    min_val = getattr(self, 'min', None)
    max_val = getattr(self, 'max', None)
    # If neither bound is defined, nothing to validate
    if min_val is None and max_val is None:
        return
    for name, value in args.items():
        try:
            numeric = float(value)
        except (TypeError, ValueError):
            raise ValueError(f'Argument "{name}" value {value} cannot be interpreted as a number for min/max validation')
        if min_val is not None and numeric < min_val:
            raise ValueError(f'Argument "{name}" value {numeric} is below minimum {min_val}')
        if max_val is not None and numeric > max_val:
            raise ValueError(f'Argument "{name}" value {numeric} exceeds maximum {max_val}')<|return|>

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if not isinstance(vars_dict, dict):
        raise TypeError('vars_dict must be a dict')
    if extra_vars is None:
        return vars_dict

    if isinstance(extra_vars, dict):
        vars_dict.update(extra_vars)
    else:
        for k, v in extra_vars:
            vars_dict[k] = v
    return vars_dict<|return|>

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # Mapping of common types that can be auto-detected
    for key, val in list(values_dict.items()):
        if isinstance(val, str):
            lower_val = val.strip().lower()
            # Boolean conversion
            if lower_val in ("true", "false", "yes", "no", "1", "0"):
                values_dict[key] = lower_val in ("true", "yes", "1")
                continue
            # Integer conversion
            try:
                int_val = int(val.strip())
                values_dict[key] = int_val
                continue
            except ValueError:
                pass
            # Float conversion
            try:
                float_val = float(val.strip())
                values_dict[key] = float_val
                continue
            except ValueError:
                pass
            # List conversion (comma separated)
            if "," in val:
                values_dict[key] = [item.strip() for item in val.split(",")]
                continue
            # Leave as string if no conversion succeeded
            values_dict[key] = val
    # Extra parser specific adjustments
    if parser_name == "virsh":
        # Example: convert CPU count to integer if present
        if "cpu" in values_dict and isinstance(values_dict["cpu"], str):
            try:
                values_dict["cpu"] = int(values_dict["cpu"])
            except ValueError:
                pass
        # Example: convert memory size to integer (MB)
        if "memory" in values_dict and isinstance(values_dict["memory"], str):
            try:
                values_dict["memory"] = int(values_dict["memory"])
            except ValueError:
                pass
    elif parser_name == "ospd":
        # Example: convert debug flag
        if "debug" in values_dict and isinstance(values_dict["debug"], str):
            values_dict["debug"] = values_dict["debug"].lower() in ("true", "yes", "1")
    # Return not needed; values_dict is modified in place.<|return|>

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json
    spec_path = os.path.join(plugin_dir, 'plugin.json')
    if not os.path.isfile(spec_path):
        return {}
    with open(spec_path, 'r', encoding='utf-8') as f:
        spec = json.load(f)

    flat = {}

    def _flatten(current, parent_key=''):
        for key, value in current.items():
            new_key = f"{parent_key}.{key}" if parent_key else key
            if isinstance(value, dict):
                _flatten(value, new_key)
            else:
                flat[new_key] = value

    _flatten(spec)
    return flat<|return|>

